mapper.sql:
from cms_state_reason r

  and (r.reason_cd like #{keyword} escape '\' or r.reason_nm ilike #{keyword} escape '\')
  and r.state_cat = #{stateCat}
  and r.use_yn = #{useYn}

mapper.update:
update cms_state_reason
   set reason_nm = #{r.reasonNm}, planned_yn = #{r.plannedYn}, sort_no = #{r.sortNo}, use_yn = #{r.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where reason_id = #{r.reasonId} and row_ver = #{r.rowVer}

mapper.sql:
where e.plant_cd = #{plantCd} and s.start_at < #{to} and (s.end_at is null or s.end_at > #{from})
   and (e.equip_cd like #{keyword} escape '\' or e.equip_nm ilike #{keyword} escape '\')
   and coalesce(nr.state_cat, s.state_cat) = #{effCat}
   and s.reason_id is null and n.note_id is null and s.state_cat not in ('PRD', 'UNKNOWN')

   and coalesce(nr.reason_cd, lr.reason_cd) = #{reasonCd}

mapper.select:
select 


 order by s.start_at desc, s.state_log_id desc
 limit #{limit}

select s.state_log_id, s.equip_id, e.plant_cd, s.state_cat, s.start_at, s.end_at
  from cms_equip_state_log s join mst_equip e on e.equip_id = s.equip_id
 where s.state_log_id = #{stateLogId}

select m.mwo_id, m.mwo_no, m.title, m.status, m.reported_at, m.down_start_at, m.down_end_at
  from cms_mwo m
 where m.equip_id = #{equipId} and m.mwo_type = 'BM' and m.status <> 'CANCELLED'
   and m.reported_at >= #{from} and m.reported_at < #{to}
 order by m.reported_at desc, m.mwo_id desc
 limit #{limit}
